window.LESSONS = window.LESSONS || [];

/* ============ 01 WHAT IS LINUX ============ */
LESSONS.push({
  id: 'what-is-linux', num: 1, cat: 'core', layer: 2, mins: 10,
  title: 'What is Linux?', short: 'Kernel, distros & the shell',
  overview: `<p>Before typing a single command, you need a mental picture of <b>what Linux actually is</b>. Spoiler: "Linux" is technically just one program, the <b>kernel</b>. Everything else is built around it.</p><p>In this lesson you'll follow a request from <b>you</b> → the <b>shell</b> → the <b>kernel</b> → the <b>hardware</b>, and see why this one free operating system runs most of the cloud.</p>`,
  hook: `<b>Customer → Waiter → Chef → Kitchen.</b> You order, the shell takes the order, the kernel cooks, the hardware is the stove.`,
  why: `Most EC2 instances, containers, Kubernetes nodes and security tools run on Linux. If you're heading for Cloud Security or Solutions Architecture, Linux is the floor you stand on.`,
  scene: { type: 'graph', nodes: [
    { id: 'you', x: 110, y: 250, icon: 'user', label: 'You', sub: 'the customer' },
    { id: 'shell', x: 320, y: 250, icon: 'terminal', label: 'Shell (bash)', sub: 'the waiter', at: 0 },
    { id: 'kernel', x: 540, y: 250, icon: 'kernel', label: 'Kernel', sub: 'the chef' },
    { id: 'hw', x: 770, y: 250, icon: 'hardware', label: 'Hardware', sub: 'CPU · RAM · disk · NIC' },
    { id: 'distro', x: 540, y: 95, icon: 'distro', label: 'Distribution', sub: 'Ubuntu · Amazon Linux · Kali', at: 1 },
    { id: 'files', x: 320, y: 400, icon: 'folder', label: '/dev  /proc', sub: 'everything is a file', at: 3 },
    { id: 'cloud', x: 770, y: 95, icon: 'cloud', label: 'The Cloud', sub: 'EC2 · containers · K8s', at: 4 }
  ], edges: [{ a: 'you', b: 'shell' }, { a: 'shell', b: 'kernel' }, { a: 'kernel', b: 'hw' }, { a: 'distro', b: 'kernel', at: 1 }, { a: 'kernel', b: 'files', at: 3 }, { a: 'hw', b: 'cloud', at: 4 }] },
  steps: [
    { t: 'Meet the kernel', sub: 'The one program that talks to hardware',
      body: `<p>The <b>kernel</b> is the core of the operating system. It's the only program allowed to touch the hardware directly: it hands out CPU time, manages memory, talks to disks and network cards, and enforces who can do what.</p><p>Linus Torvalds wrote the first Linux kernel in 1991. Every app you run asks the kernel for help through <b>system calls</b> ("please open this file", "please send this packet").</p>`,
      analogy: `The kernel is the <b>head chef</b>. Customers never walk into the kitchen. They place orders, and the chef decides which burner, pan and ingredient to use.`,
      hook: `<b>Kernel = Kitchen boss.</b> Both start with K. Only the kernel touches the stove.`,
      words: ['kernel', 'system call', 'hardware', 'Linus Torvalds 1991'],
      flow: { from: 'kernel', to: 'hw', label: 'SYSCALL', detail: ['read(disk, 4096 bytes)'], color: 'blue' }, focus: ['kernel', 'hw'],
      cmds: [{ c: 'uname -r', o: '6.8.0-45-generic', k: 'sys' }],
      cmd: { k: 'sys', tag: 'ASK THE KERNEL', who: 'you → kernel', code: 'uname -r\n6.8.0-45-generic   ← kernel version' },
      facts: [['WRITTEN IN', 'C (plus a little assembly and, lately, Rust)'], ['LICENSE', 'GPLv2: free to use, study, change'], ['JOB', 'CPU scheduling, memory, devices, security']] },
    { t: 'Distributions', sub: 'Kernel + tools + package manager',
      body: `<p>A raw kernel can't do much on its own. A <b>distribution (distro)</b> bundles the kernel with tools, a shell, a package manager and default settings, so you get a usable system.</p><p><b>Ubuntu</b> and <b>Debian</b> use <code>apt</code>. <b>Red Hat (RHEL)</b>, <b>Amazon Linux</b> and Fedora use <code>dnf</code>/<code>yum</code>. <b>Kali</b> is Debian-based and packed with security tools.</p>`,
      analogy: `The kernel is the <b>engine</b>; a distro is the <b>car model</b>. A Toyota and a Ford can share engine ideas but have different dashboards, seats and service manuals.`,
      hook: `<b>Same engine, different cars.</b> Ubuntu, Amazon Linux and Kali all run the Linux engine.`,
      words: ['distro', 'Ubuntu/Debian = apt', 'RHEL/Amazon Linux = dnf', 'Kali = security'],
      flow: { from: 'distro', to: 'kernel', label: 'BUNDLES', detail: ['kernel + bash + apt/dnf', '+ default configs'], color: 'purple' }, focus: ['distro', 'kernel'],
      cmds: [{ c: 'cat /etc/os-release', o: 'NAME="Ubuntu"\nVERSION="24.04 LTS (Noble Numbat)"\nID=ubuntu', k: 'text' }],
      cmd: { k: 'text', tag: 'WHICH DISTRO?', who: 'read a config file', code: 'cat /etc/os-release' },
      cloud: `On AWS you'll mostly meet <b>Amazon Linux 2023</b> (user <code>ec2-user</code>, <code>dnf</code>) and <b>Ubuntu</b> (user <code>ubuntu</code>, <code>apt</code>). Same skills, different package manager.` },
    { t: 'The shell', sub: 'Your translator to the kernel',
      body: `<p>The <b>shell</b> is a program that reads what you type, figures out what you mean, and asks the kernel to do it. The most common shell is <b>bash</b> (Bourne Again SHell). Others: <code>zsh</code>, <code>sh</code>, <code>fish</code>.</p><p>The <b>terminal</b> is just the window. The <b>shell</b> is the brain running inside it.</p>`,
      analogy: `The shell is the <b>waiter</b>. You say "one adobo, extra rice"; the waiter turns it into a proper kitchen ticket the chef understands.`,
      hook: `<b>Terminal = window, Shell = waiter.</b> You talk to the waiter through the window.`,
      words: ['shell', 'bash', 'terminal', 'command interpreter'],
      flow: { from: 'you', to: 'shell', label: 'YOU TYPE', detail: ['echo $SHELL'], color: 'green' }, focus: ['you', 'shell'],
      cmds: [{ c: 'echo $SHELL', o: '/bin/bash', k: 'sys' }, { c: 'whoami', o: 'alice', k: 'user' }],
      cmd: { k: 'sys', tag: 'WHICH SHELL?', who: 'you → shell', code: 'echo $SHELL\n/bin/bash' } },
    { t: 'Everything is a file', sub: 'The Linux superpower',
      body: `<p>Linux treats almost everything as a <b>file</b>: documents, folders, your keyboard, disks (<code>/dev/sda</code>), even running processes and CPU info (<code>/proc/cpuinfo</code>).</p><p>That means one small set of tools (<code>cat</code>, <code>grep</code>, <code>ls</code>) works on <b>everything</b>. Learn the file tools once, use them everywhere.</p>`,
      analogy: `Imagine a hotel where every room, elevator and light switch has a <b>room number</b>. Staff only need one skill: "go to room X". Linux gives everything a path.`,
      hook: `<b>"If it exists, it has a path."</b> Hardware, settings and processes all live in the file tree.`,
      words: ['everything is a file', '/dev = devices', '/proc = live kernel info'],
      flow: { from: 'kernel', to: 'files', label: 'EXPOSES', detail: ['/proc/cpuinfo', '/dev/sda'], color: 'teal' }, focus: ['kernel', 'files'],
      cmds: [{ c: 'cat /proc/cpuinfo | grep "model name"', o: 'model name : Virtual CPU @ 2.40GHz', k: 'text' }, { c: 'ls /dev | head -3', o: 'autofs\nblock\nnull', k: 'nav' }],
      cmd: { k: 'text', tag: 'READ THE CPU', who: 'a "file" made by the kernel', code: 'cat /proc/cpuinfo' } },
    { t: 'Why Linux runs the cloud', sub: 'Free, stable, scriptable, secure',
      body: `<p>The large majority of cloud servers and virtually all containers run Linux. Why?</p><p><b>Free</b> (no license per server), <b>stable</b> (runs for years without reboot), <b>scriptable</b> (everything can be automated from the shell), <b>lightweight</b> (no GUI needed), and <b>open</b> (security teams can inspect the code).</p>`,
      analogy: `Renting a car with <b>no license fee, no dashboard you don't need, and a manual you can rewrite</b>. Of course the cloud providers pick that one.`,
      hook: `<b>F.S.S.L.O.</b>: Free, Stable, Scriptable, Lightweight, Open.`,
      words: ['headless server', 'automation', 'open source', 'containers'],
      flow: { from: 'hw', to: 'cloud', label: 'POWERS', detail: ['EC2 · ECS · EKS · Lambda'], color: 'amber' }, focus: ['cloud', 'kernel'],
      cloud: `Even AWS Lambda functions run on Linux under the hood (Firecracker micro-VMs). Knowing Linux helps you debug almost any AWS compute service.`,
      cmds: [{ c: 'hostname', o: 'linux-lab', k: 'sys' }] },
    { t: 'Your first commands', sub: 'Ask the system who and where it is',
      body: `<p>Four harmless commands you'll use on every new server you log into. Think of them as <b>"Where am I, who am I, what is this machine?"</b></p><p><code>whoami</code> → your user. <code>hostname</code> → machine name. <code>uname -a</code> → kernel details. <code>uptime</code> → how long it's been running and how busy it is.</p>`,
      analogy: `Like waking up in a hotel: check your <b>name tag</b> (whoami), the <b>hotel name</b> (hostname), the <b>building specs</b> (uname) and <b>how long the lobby's been open</b> (uptime).`,
      hook: `<b>WHO-HOST-UNAME-UP</b>: the four-command "server hello".`,
      words: ['whoami', 'hostname', 'uname -a', 'uptime'],
      flow: { from: 'shell', to: 'kernel', label: 'uname -a', detail: ['Linux linux-lab 6.8.0', 'x86_64 GNU/Linux'], color: 'green' },
      cmds: [{ c: 'whoami', o: 'alice', k: 'user' }, { c: 'uname -a', o: 'Linux linux-lab 6.8.0-45-generic #45-Ubuntu SMP x86_64 GNU/Linux', k: 'sys' }, { c: 'uptime', o: ' 09:12:44 up 1:30,  1 user,  load average: 0.08, 0.03, 0.01', k: 'sys' }],
      cmd: { k: 'sys', tag: 'SERVER HELLO', who: 'run these on every new box', code: 'whoami\nhostname\nuname -a\nuptime' } }
  ],
  summary: { title: 'You know what Linux is', sub: 'The kernel, wrapped in a distro, driven by a shell', text: `<p>You type into a <b>terminal</b>; the <b>shell</b> (bash) interprets it; the <b>kernel</b> does the real work on the <b>hardware</b>. A <b>distro</b> packages it all, and because everything is a file, a few tools go a very long way.</p>`, facts: [['KERNEL', 'Core program, talks to hardware'], ['DISTRO', 'Kernel + tools + package manager'], ['SHELL', 'bash: interprets your commands']] },
  quiz: [
    { q: 'Strictly speaking, what is "Linux"?', a: ['A distribution like Ubuntu', 'The kernel', 'The bash shell', 'A desktop environment'], c: 1, why: 'Linux is the kernel. Ubuntu, Amazon Linux and Kali are distributions built around it.' },
    { q: 'In the restaurant analogy, the shell is the…', a: ['Chef', 'Stove', 'Waiter', 'Customer'], c: 2, why: 'The shell takes your "order" (command) and passes it to the kernel (chef).' },
    { q: 'Amazon Linux 2023 uses which package manager?', a: ['apt', 'dnf', 'pacman', 'brew'], c: 1, why: 'Red Hat-family distros (RHEL, Fedora, Amazon Linux) use dnf/yum. Debian/Ubuntu use apt.' },
    { q: 'Where would you find live info about the CPU?', a: ['/etc/cpu', '/home/cpu', '/proc/cpuinfo', '/var/cpu'], c: 2, why: '/proc is a virtual filesystem the kernel fills with live system info.' }
  ],
  next: `You've met the waiter (the shell). Next you'll learn to <b>talk to it fluently</b>: decode the prompt, build commands like sentences, and pick up the shortcuts that make pros look like they're typing at 200 WPM.`,
  cheat: [['uname -a', 'kernel & system info'], ['cat /etc/os-release', 'which distro'], ['whoami', 'current user'], ['hostname', 'machine name'], ['uptime', 'running time & load'], ['echo $SHELL', 'which shell']]
});

/* ============ 02 TERMINAL & SHELL ============ */
LESSONS.push({
  id: 'terminal-shell', num: 2, cat: 'core', layer: 4, mins: 12,
  title: 'Terminal & Shell', short: 'Prompts, command grammar & shortcuts',
  overview: `<p>The terminal looks scary because it's silent and blinking. But every command follows the <b>same grammar</b>, and once you can read the prompt and the grammar, you can read any command.</p>`,
  hook: `<b>Verb, adverb, noun.</b> <code>ls -l /etc</code> = "list, in long form, the /etc folder".`,
  why: `Every cloud server you SSH into, every CI/CD pipeline step and every Dockerfile <code>RUN</code> line is a shell command. Fluency here pays off everywhere.`,
  scene: { type: 'graph', nodes: [
    { id: 'you', x: 100, y: 240, icon: 'user', label: 'You' },
    { id: 'term', x: 280, y: 240, icon: 'terminal', label: 'Terminal', sub: 'the window' },
    { id: 'bash', x: 470, y: 240, icon: 'gear', label: 'bash', sub: 'parses the command' },
    { id: 'path', x: 660, y: 120, icon: 'folder', label: '$PATH dirs', sub: '/usr/bin  /bin', at: 4 },
    { id: 'man', x: 660, y: 370, icon: 'book', label: 'man pages', sub: 'built-in manual', at: 2 },
    { id: 'kernel', x: 820, y: 240, icon: 'kernel', label: 'Kernel' }
  ], edges: [{ a: 'you', b: 'term' }, { a: 'term', b: 'bash' }, { a: 'bash', b: 'kernel' }, { a: 'bash', b: 'path', at: 4 }, { a: 'bash', b: 'man', at: 2 }] },
  steps: [
    { t: 'Read the prompt', sub: 'who @ where : folder $',
      body: `<p>Before you type, the shell shows a <b>prompt</b>:</p><p><code>alice@linux-lab:~/project$</code></p><p><b>alice</b> = who you are. <b>linux-lab</b> = which machine. <b>~/project</b> = which folder (<code>~</code> means your home). <b>$</b> = normal user. If it ends in <b>#</b>, you're <b>root</b> (the all-powerful admin), so slow down.</p>`,
      analogy: `The prompt is your <b>GPS status bar</b>: driver name, city, street, and whether you're driving a normal car ($) or a fire truck (#).`,
      hook: `<b>$ = civilian, # = root.</b> A hash means "handle with care".`,
      words: ['prompt', 'user@host', '~ = home', '$ vs #'],
      flow: { from: 'term', to: 'you', label: 'PROMPT', detail: ['alice@linux-lab:~$'], color: 'blue' }, focus: ['term', 'you'],
      cmds: [{ c: 'pwd', o: '/home/alice', k: 'nav' }],
      facts: [['$', 'regular user'], ['#', 'root (superuser)'], ['~', 'your home directory, e.g. /home/alice']] },
    { t: 'Command grammar', sub: 'command  -options  arguments',
      body: `<p>Almost every command has three parts:</p><p><b>command</b> (the verb: what to do) · <b>options/flags</b> (the adverb: how to do it, usually starting with <code>-</code> or <code>--</code>) · <b>arguments</b> (the noun: what to do it to).</p><p><code>ls -la /etc</code> → list · long format + all files · in /etc. Short flags can be combined: <code>-l -a</code> = <code>-la</code>.</p>`,
      analogy: `It's a sentence: <b>"Run (verb) quickly (adverb) to the store (noun)."</b> → <code>ls -l /etc</code>.`,
      hook: `<b>V-A-N: Verb, Adverb, Noun.</b> Command, flag, target.`,
      words: ['command', '-short flag', '--long-flag', 'argument', 'case-sensitive'],
      flow: { from: 'term', to: 'bash', label: 'PARSE', detail: ['cmd: ls', 'opts: -l -a', 'arg: /etc'], color: 'green' }, focus: ['term', 'bash'],
      cmds: [{ c: 'ls -la /etc', o: 'drwxr-xr-x  1 root root 4096 Nov 13 09:00 .\n-rw-r--r--  1 root root   61 Nov 13 09:00 passwd ...', k: 'nav' }],
      cmd: { k: 'nav', tag: 'ANATOMY', who: 'verb · adverb · noun', code: 'ls   -la   /etc\n│     │     └─ argument (what)\n│     └─ options (how)\n└─ command (do what)' },
      warn: `Linux is <b>case-sensitive</b>: <code>File.txt</code> and <code>file.txt</code> are two different files, and <code>LS</code> is not a command.` },
    { t: 'Getting help', sub: 'man, --help, and q to quit',
      body: `<p>Nobody memorizes every flag. Pros look things up constantly:</p><p><code>man ls</code> opens the full manual (scroll with arrows, search with <code>/word</code>, quit with <b>q</b>). <code>ls --help</code> prints a quick summary. Many people also install <code>tldr</code> for example-first help.</p>`,
      analogy: `<code>man</code> is the <b>full instruction booklet</b> in the box; <code>--help</code> is the <b>sticker on the lid</b>.`,
      hook: `<b>"Man, I need help!"</b> → <code>man</code> or <code>--help</code>. Stuck in a manual? Press <b>q</b> to Quit.`,
      words: ['man', '--help', 'q to quit', '/search'],
      flow: { from: 'bash', to: 'man', label: 'man ls', detail: ['LS(1) User Commands'], color: 'purple' }, focus: ['bash', 'man'],
      cmds: [{ c: 'man ls', o: 'LS(1)    User Commands    LS(1)\nNAME  ls - list directory contents  (press q to quit)', k: 'sys' }, { c: 'ls --help | head -2', o: 'Usage: ls [OPTION]... [FILE]...\nList information about the FILEs (the current directory by default).', k: 'sys' }] },
    { t: 'Speed keys', sub: 'Tab, ↑, Ctrl+C, Ctrl+R, Ctrl+L',
      body: `<p><b>Tab</b>: autocompletes commands and file names (press twice to see options). <b>↑ / ↓</b>: scroll through previous commands. <b>Ctrl+C</b>: cancel/kill the running command. <b>Ctrl+R</b>: search your history. <b>Ctrl+L</b>: clear the screen. <code>history</code>: list everything you ran.</p>`,
      analogy: `Tab is <b>autocomplete on your phone keyboard</b>; ↑ is <b>"redial last number"</b>; Ctrl+C is the <b>emergency stop button</b>.`,
      hook: `<b>Tab to finish, ↑ to repeat, Ctrl+C to escape.</b>`,
      words: ['Tab completion', 'history', 'Ctrl+C', 'Ctrl+R', 'Ctrl+L'],
      flow: { from: 'you', to: 'term', label: 'KEYS', detail: ['Tab ↹  ↑  Ctrl+C'], color: 'amber' }, focus: ['you', 'term'],
      cmds: [{ c: 'history | tail -3', o: '  12  ls -la /etc\n  13  man ls\n  14  history | tail -3', k: 'sys' }],
      cloud: `When SSH'd into a production server, <b>Tab completion prevents typos</b> in long paths like <code>/etc/nginx/sites-available/</code>. Typos on servers are how outages start.` },
    { t: 'Variables & $PATH', sub: 'How bash finds programs',
      body: `<p>The shell keeps <b>environment variables</b>, named values like <code>$HOME</code>, <code>$USER</code> and <code>$PATH</code>.</p><p><code>$PATH</code> is a list of folders bash searches, in order, when you type a command. Type <code>ls</code> and bash checks <code>/usr/local/bin</code>, then <code>/usr/bin</code>… until it finds the <code>ls</code> program. <code>which ls</code> shows where it found it.</p>`,
      analogy: `$PATH is your <b>contact list search order</b>: "check Family, then Work, then Friends" until a name matches.`,
      hook: `<b>PATH = the places bash looks.</b> "Command not found" usually means "not in PATH".`,
      words: ['environment variable', '$HOME', '$PATH', 'which', 'export'],
      flow: { from: 'bash', to: 'path', label: 'LOOKUP', detail: ['ls → /usr/bin/ls ✓'], color: 'teal' }, focus: ['bash', 'path'],
      cmds: [{ c: 'echo $PATH', o: '/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin', k: 'sys' }, { c: 'which python3', o: '/usr/bin/python3', k: 'sys' }, { c: 'export GREETING="hi"', o: '', k: 'sys' }],
      cmd: { k: 'sys', tag: 'SET A VARIABLE', who: 'available to child programs', code: 'export API_URL="https://api.example.com"\necho $API_URL' },
      cloud: `In DevOps, secrets and settings are often passed as <b>environment variables</b> (12-factor apps, Docker <code>-e</code>, Lambda env vars). Never <code>echo</code> secrets into logs.` }
  ],
  summary: { title: 'You speak shell', sub: 'Prompt → grammar → help → shortcuts → PATH', text: `<p>You can read a prompt, break any command into <b>verb · adverb · noun</b>, find help without Google, move fast with Tab and history, and understand why "command not found" happens.</p>` },
  quiz: [
    { q: 'Your prompt ends in #. What does that mean?', a: ['You are in a comment', 'You are root', 'The command failed', 'You are in /tmp'], c: 1, why: '# indicates the root (superuser) shell; $ is a regular user.' },
    { q: 'In `tar -czf backup.tgz /etc`, what is /etc?', a: ['A command', 'An option', 'An argument', 'A variable'], c: 2, why: 'Arguments are the "nouns": what the command acts on.' },
    { q: 'You typed `htop` and got "command not found". Most likely cause?', a: ['Wrong user', 'It is not installed or not in $PATH', 'The kernel is broken', 'You need Tab'], c: 1, why: 'Bash searched every folder in $PATH and didn\'t find it.' },
    { q: 'Which key cancels a running command?', a: ['Ctrl+Z', 'Ctrl+C', 'Esc', 'q'], c: 1, why: 'Ctrl+C sends SIGINT (interrupt). Ctrl+Z only pauses it.' }
  ],
  next: `You can talk to the shell. But where are you? Linux has <b>no C: drive</b>. Next: the map of the Linux filesystem, where every folder has a job (and one of them is literally a diary of everything that happened on the server).`,
  cheat: [['man <cmd>', 'full manual (q quits)'], ['<cmd> --help', 'quick help'], ['history', 'past commands'], ['Ctrl+R', 'search history'], ['echo $PATH', 'where bash looks'], ['which <cmd>', 'path of a program'], ['export VAR=val', 'set env variable']]
});

/* ============ 03 FILESYSTEM MAP ============ */
LESSONS.push({
  id: 'filesystem', num: 3, cat: 'core', layer: 3, mins: 12,
  title: 'The Filesystem Map', short: 'One tree, starting at /',
  overview: `<p>Windows has drives (C:, D:). Linux has <b>one single tree</b> that starts at <code>/</code> (called "root"). Disks, USB sticks and network shares are all <b>mounted</b> somewhere inside that tree.</p><p>Every top-level folder has a job. Learn the jobs and you'll always know where to look.</p>`,
  hook: `<b>Linux is a house.</b> / = the land, /home = bedrooms, /root = the master's room, /etc = the fuse box, /var/log = the CCTV recorder, /tmp = the kitchen table, /bin = the toolshed.`,
  why: `Troubleshooting a server is mostly "know which folder": configs in <code>/etc</code>, logs in <code>/var/log</code>, web files in <code>/var/www</code>. Security auditors check these exact paths.`,
  scene: { type: 'tree', title: 'THE LINUX HOUSE', items: [
    [0, '/', 'root of everything (the land)', 'd'],
    [1, 'bin', 'essential programs: ls, cp, bash (toolshed)', 'd', 4],
    [1, 'boot', 'kernel & bootloader files', 'd', 4],
    [1, 'dev', 'devices as files: disks, null', 'd', 5],
    [1, 'etc', 'system configuration (fuse box)', 'd', 1],
    [2, 'passwd', 'list of user accounts', 'f', 1],
    [2, 'ssh', 'SSH server config lives here', 'd', 1],
    [1, 'home', 'users’ personal folders (bedrooms)', 'd', 2],
    [2, 'alice', 'alice’s home = ~', 'd', 2],
    [1, 'root', 'root user’s home (master bedroom)', 'd', 2],
    [1, 'opt', 'optional/3rd-party software', 'd', 4],
    [1, 'proc', 'live kernel & process info (virtual)', 'd', 5],
    [1, 'tmp', 'temporary scratch space (kitchen table)', 'd', 5],
    [1, 'usr', 'user programs & libraries', 'd', 4],
    [2, 'bin', 'most commands live here', 'd', 4],
    [1, 'var', 'variable data that grows', 'd', 3],
    [2, 'log', 'logs: the CCTV recorder', 'd', 3],
    [2, 'www', 'web server files', 'd', 3]
  ] },
  steps: [
    { t: 'Root: /', sub: 'One tree, no drive letters',
      body: `<p>Everything starts at <code>/</code>. A second disk isn't "D:", it gets <b>mounted</b> into a folder like <code>/mnt/data</code> or <code>/data</code>.</p><p>Paths use forward slashes: <code>/home/alice/notes.txt</code> means "start at root, go into home, then alice, then the file".</p>`,
      analogy: `<code>/</code> is the <b>plot of land</b>. Every building, room and cupboard sits on it. Buy a new storage shed (disk)? You place it <b>somewhere on the same land</b>.`,
      hook: `<b>Slash is the start.</b> Every absolute path begins with /.`,
      words: ['/ = root directory', 'mount', 'absolute path', 'forward slash'],
      focus: ['/'], pin: '/',
      cmds: [{ c: 'ls /', o: 'bin  boot  dev  etc  home  opt  proc  root  tmp  usr  var', k: 'nav' }],
      warn: `Don't confuse <b>/</b> (the root <i>directory</i>) with <b>/root</b> (the root <i>user's</i> home folder) or <b>root</b> (the admin <i>user</i>). Same word, three meanings.` },
    { t: '/etc: configuration', sub: 'The fuse box of the system',
      body: `<p><code>/etc</code> holds <b>system-wide configuration files</b>: plain text you can read and edit. <code>/etc/passwd</code> lists users, <code>/etc/hosts</code> maps names to IPs, <code>/etc/ssh/sshd_config</code> controls SSH.</p><p>Change a service's behaviour? 90% of the time you edit a file in <code>/etc</code>.</p>`,
      analogy: `<code>/etc</code> is the <b>fuse box & control panel</b> of the house. Flip a setting here and the whole house behaves differently.`,
      hook: `<b>/etc = "Edit To Configure".</b>`,
      words: ['/etc', 'config files', '/etc/passwd', '/etc/ssh/sshd_config'],
      focus: ['etc', 'passwd', 'ssh'], pin: 'etc',
      cmds: [{ c: 'ls /etc', o: 'group  hostname  hosts  os-release  passwd  shadow  ssh/', k: 'nav', d: '/' }, { c: 'head -2 /etc/passwd', o: 'root:x:0:0:root:/root:/bin/bash\nalice:x:1001:1001:Alice:/home/alice:/bin/bash', k: 'text' }],
      cloud: `Configuration-management and IaC tools (Ansible, cloud-init, user data scripts) mostly do one thing: <b>write files into /etc and restart services</b>.` },
    { t: '/home and /root', sub: 'Where users live',
      body: `<p>Each regular user gets a folder in <code>/home</code>: <code>/home/alice</code>, <code>/home/bob</code>. That's their <b>home directory</b>, written as <code>~</code>. Personal files, SSH keys (<code>~/.ssh</code>) and settings (<code>~/.bashrc</code>) live there.</p><p>The admin user <b>root</b> is special: its home is <code>/root</code>, not /home/root.</p>`,
      analogy: `<code>/home</code> is the <b>bedroom hallway</b>: one room per family member. <code>/root</code> is the <b>locked master bedroom</b>, apart from the others.`,
      hook: `<b>~ = home sweet home.</b> Root sleeps in /root.`,
      words: ['/home/<user>', '~', '/root', 'dotfiles (.bashrc)'],
      focus: ['home', 'alice', 'root'], pin: 'alice',
      cmds: [{ c: 'echo ~', o: '/home/alice', k: 'nav' }, { c: 'ls /root', o: "ls: cannot open directory '/root': Permission denied", k: 'nav', x: 2 }] },
    { t: '/var/log: logs', sub: 'The CCTV recorder',
      body: `<p><code>/var</code> = <b>var</b>iable data that grows over time: logs, caches, mail, databases, web content (<code>/var/www</code>).</p><p><code>/var/log</code> is where services write <b>logs</b>: <code>syslog</code>/<code>messages</code> for general events and <code>auth.log</code>/<code>secure</code> for logins and sudo. When something breaks, or someone breaks in, you look here first.</p>`,
      analogy: `<code>/var/log</code> is the <b>CCTV recorder</b> of the house. It watches everything and rewinds the tape when something goes wrong.`,
      hook: `<b>"Something broke? Var-log it."</b>`,
      words: ['/var', '/var/log', 'syslog', 'auth.log', '/var/www'],
      focus: ['var', 'log', 'www'], pin: 'log',
      cmds: [{ c: 'ls /var/log', o: 'auth.log  syslog', k: 'nav' }, { c: 'sudo tail -2 /var/log/auth.log', o: 'Nov 13 08:59:14 sshd[901]: Failed password for root from 203.0.113.9\nNov 13 09:01:03 sshd[944]: Accepted publickey for alice', k: 'text' }],
      cloud: `<b>Security</b>: repeated "Failed password" lines in auth.log = a brute-force attempt. On AWS, the CloudWatch agent ships these files off the server so attackers can't erase them.` },
    { t: 'Program folders', sub: '/bin, /usr/bin, /sbin, /opt, /boot',
      body: `<p>Commands are just program files. Essential ones live in <code>/bin</code> and <code>/usr/bin</code>; admin tools in <code>/sbin</code> and <code>/usr/sbin</code>. On modern distros, <code>/bin</code> is just a shortcut to <code>/usr/bin</code>.</p><p><code>/opt</code> holds big third-party apps. <code>/boot</code> holds the kernel itself and the bootloader.</p>`,
      analogy: `<code>/bin</code> and <code>/usr/bin</code> are the <b>toolshed</b>. <code>/sbin</code> is the <b>locked cabinet of power tools</b> for the admin. <code>/opt</code> is the <b>garage for big rented equipment</b>.`,
      hook: `<b>bin = binaries = tools.</b> s-bin = system (admin) binaries.`,
      words: ['/bin', '/usr/bin', '/sbin', '/opt', '/boot'],
      focus: ['bin', 'usr', 'opt', 'boot'], pin: 'usr',
      cmds: [{ c: 'which ls bash', o: '/usr/bin/ls\n/usr/bin/bash', k: 'sys' }] },
    { t: 'Virtual & temp folders', sub: '/dev, /proc, /tmp',
      body: `<p><code>/dev</code>: devices as files (<code>/dev/sda</code> = first disk, <code>/dev/null</code> = a black hole that deletes whatever you send it).</p><p><code>/proc</code>: not on disk at all; the kernel generates it live. Every running process has a folder <code>/proc/&lt;PID&gt;</code>.</p><p><code>/tmp</code>: scratch space anyone can write to; usually wiped on reboot.</p>`,
      analogy: `<code>/dev</code> = the <b>doors to the appliances</b>. <code>/proc</code> = a <b>live dashboard</b> projected on the wall. <code>/tmp</code> = the <b>kitchen table</b>: anyone puts things there, it gets cleared every night.`,
      hook: `<b>dev = devices, proc = processes, tmp = temporary.</b>`,
      words: ['/dev/null', '/proc/<PID>', '/tmp', 'virtual filesystem'],
      focus: ['dev', 'proc', 'tmp'], pin: 'tmp',
      cmds: [{ c: 'echo "gone" > /dev/null', o: '', k: 'file' }, { c: 'cat /proc/uptime', o: '5432.10 9876.54', k: 'text' }],
      cloud: `<b>Security</b>: attackers love <code>/tmp</code> because everyone can write there. Hardened servers mount it with <code>noexec</code> so programs dropped there can't run.` }
  ],
  summary: { title: 'You have the map', sub: 'Every folder has a job', text: `<p>One tree from <code>/</code>. Config in <code>/etc</code>, people in <code>/home</code>, the admin in <code>/root</code>, logs in <code>/var/log</code>, tools in <code>/usr/bin</code>, live system info in <code>/proc</code>, scratch in <code>/tmp</code>.</p>`, facts: [['CONFIG', '/etc'], ['LOGS', '/var/log'], ['USERS', '/home/<name>'], ['PROGRAMS', '/usr/bin']] },
  quiz: [
    { q: 'The SSH server config is most likely in…', a: ['/home/ssh', '/var/ssh', '/etc/ssh/sshd_config', '/bin/ssh'], c: 2, why: 'System configuration lives in /etc.' },
    { q: 'Where do you look first after a suspected break-in?', a: ['/tmp', '/var/log', '/boot', '/opt'], c: 1, why: '/var/log (auth.log / secure) records logins, sudo use and failures.' },
    { q: 'What is /root?', a: ['The top of the filesystem', 'The root user’s home folder', 'The kernel', 'A device'], c: 1, why: '/ is the top of the tree; /root is the admin user’s home.' },
    { q: 'Which folder is generated live by the kernel and is not on disk?', a: ['/proc', '/etc', '/usr', '/home'], c: 0, why: '/proc is a virtual filesystem showing processes and kernel state.' }
  ],
  next: `You've seen the map from above. Now it's time to <b>walk the streets</b>: move around with <code>cd</code>, look around with <code>ls</code>, and learn the shortcuts (<code>.</code>, <code>..</code>, <code>~</code>, <code>-</code>) that make you fast.`,
  cheat: [['/etc', 'configuration'], ['/var/log', 'logs'], ['/home/<user>', 'user files (~)'], ['/root', 'root’s home'], ['/usr/bin', 'commands'], ['/proc', 'live kernel info'], ['/tmp', 'temp, world-writable'], ['/dev/null', 'black hole']]
});

/* ============ 04 NAVIGATION ============ */
LESSONS.push({
  id: 'navigation', num: 4, cat: 'core', layer: 4, mins: 10,
  title: 'Moving Around', short: 'pwd, ls, cd and path shortcuts',
  overview: `<p>Three commands do 90% of navigation: <b>pwd</b> (where am I?), <b>ls</b> (what's here?), <b>cd</b> (go there). Add four shortcuts (<code>.</code> <code>..</code> <code>~</code> <code>-</code>) and you'll move like a local.</p>`,
  hook: `<b>Where? What? Go!</b> → <code>pwd</code>, <code>ls</code>, <code>cd</code>.`,
  why: `On a server with no GUI, the shell is your only file explorer. Finding a config or a log file quickly is a daily DevOps task.`,
  scene: { type: 'tree', title: 'YOU ARE HERE', items: [
    [0, '/', '', 'd'], [1, 'etc', '', 'd'], [2, 'ssh', '', 'd'], [1, 'home', '', 'd'], [2, 'alice', '~ (home)', 'd'], [3, '.bashrc', 'hidden file (starts with .)', 'f', 1], [3, 'notes.txt', '', 'f'], [3, 'project', '', 'd'], [4, 'README.md', '', 'f'], [4, 'script.sh', '', 'f'], [2, 'bob', '', 'd'], [1, 'var', '', 'd'], [2, 'log', '', 'd']
  ] },
  steps: [
    { t: 'pwd: where am I?', sub: 'Print Working Directory',
      body: `<p>You're always "standing" in some folder: the <b>working directory</b>. <code>pwd</code> prints its full path. When you log in, you start in your home: <code>/home/alice</code>.</p>`,
      analogy: `<code>pwd</code> is the <b>"You are here" pin</b> on a mall map.`,
      hook: `<b>pwd = "Point Where I'm Drawn"</b>, the red pin on the map.`,
      words: ['pwd', 'working directory', 'home directory'],
      pin: 'alice', focus: ['alice'],
      cmds: [{ c: 'pwd', o: '/home/alice', k: 'nav' }] },
    { t: 'ls: look around', sub: 'List what’s in a folder',
      body: `<p><code>ls</code> lists files. The flags you'll use constantly:</p><p><code>-l</code> long format (permissions, owner, size, date) · <code>-a</code> all, including <b>hidden files</b> (names starting with <code>.</code>) · <code>-h</code> human sizes (K, M, G) · <code>-t</code> newest first.</p><p>Classic combo: <code>ls -lah</code>.</p>`,
      analogy: `<code>ls</code> = <b>looking around the room</b>. <code>ls -a</code> = also <b>checking under the bed</b>, where dotfiles hide.`,
      hook: `<b>"ls -lah"</b>: say it like "<b>la</b>h-di-dah": long, all, human.`,
      words: ['ls -l', 'ls -a', 'hidden files (.name)', 'ls -lah'],
      pin: 'alice', focus: ['.bashrc', 'notes.txt', 'project'],
      cmds: [{ c: 'ls', o: 'notes.txt  project/', k: 'nav' }, { c: 'ls -la', o: 'drwxr-x--- 1 alice alice   4096 .\n-rw-r--r-- 1 alice alice     43 .bashrc\n-rw-r--r-- 1 alice alice     88 notes.txt\ndrwxrwxr-x 1 alice developers 4096 project', k: 'nav' }] },
    { t: 'cd: go somewhere', sub: 'Absolute vs relative paths',
      body: `<p><code>cd</code> = change directory. You can give it two kinds of path:</p><p><b>Absolute</b>: starts with <code>/</code>, works from anywhere: <code>cd /var/log</code>.<br><b>Relative</b>: starts from where you are: <code>cd project</code> (only works if <i>project</i> is right here).</p>`,
      analogy: `Absolute path = a <b>full street address</b> (works from any city). Relative path = <b>"two doors down"</b> (only makes sense from where you stand).`,
      hook: `<b>Slash first = full address. No slash = "from here".</b>`,
      words: ['cd', 'absolute path', 'relative path'],
      pin: 'project', focus: ['project'],
      cmds: [{ c: 'cd project', o: '', k: 'nav' }, { c: 'pwd', o: '/home/alice/project', k: 'nav', d: '~/project' }] },
    { t: 'Path shortcuts', sub: '.  ..  ~  -',
      body: `<p><code>.</code> = this folder. <code>..</code> = the parent (one level up). <code>~</code> = your home. <code>cd -</code> = jump back to the previous folder (like a TV remote's "last channel").</p><p><code>cd ../..</code> climbs two levels. <code>cd</code> with nothing goes home.</p>`,
      analogy: `<code>..</code> is the <b>elevator going up one floor</b>. <code>~</code> is the <b>"take me home" button</b> in a ride-hailing app. <code>cd -</code> is the <b>"previous channel" button</b>.`,
      hook: `<b>One dot: here. Two dots: up. Tilde: home. Dash: back.</b>`,
      words: ['. current', '.. parent', '~ home', 'cd - previous'],
      pin: 'log', focus: ['log'],
      cmds: [{ c: 'cd ..', o: '', k: 'nav', d: '~/project' }, { c: 'cd /var/log', o: '', k: 'nav' }, { c: 'cd -', o: '/home/alice', k: 'nav', d: '/var/log' }, { c: 'cd ~/project && pwd', o: '/home/alice/project', k: 'nav' }] },
    { t: 'Tab & tree', sub: 'Never type a full path again',
      body: `<p>Type <code>cd /v</code> then <b>Tab</b> → <code>cd /var/</code>. Then <code>l</code> + Tab → <code>/var/log/</code>. If nothing happens, press Tab twice to see all matches.</p><p><code>tree</code> (install it if missing) draws the whole folder structure, a great way to understand a new project.</p>`,
      analogy: `Tab completion is <b>autocomplete in a search bar</b>: type a few letters, accept the suggestion.`,
      hook: `<b>Type 3 letters, hit Tab.</b> Fewer keystrokes, zero typos.`,
      words: ['Tab Tab', 'tree', 'autocomplete'],
      pin: 'alice', focus: ['alice', 'project', 'README.md', 'script.sh', 'notes.txt'],
      cmds: [{ c: 'tree ~', o: '/home/alice\n├── notes.txt\n└── project\n    ├── README.md\n    └── script.sh', k: 'nav' }] }
  ],
  summary: { title: 'You can navigate', sub: 'pwd · ls · cd · . .. ~ -', text: `<p>You know where you are, what's around you, and how to move by absolute or relative paths. These three commands will be in nearly every session you ever open.</p>` },
  quiz: [
    { q: 'You are in /home/alice/project. Where does `cd ..` take you?', a: ['/', '/home', '/home/alice', '/home/alice/project/..'], c: 2, why: '.. means the parent: one level up.' },
    { q: 'Which shows hidden files?', a: ['ls -h', 'ls -a', 'ls -t', 'ls -r'], c: 1, why: '-a = all, including dotfiles. -h means human-readable sizes.' },
    { q: 'Which path works no matter where you currently are?', a: ['project/src', '../log', '/var/log', './notes.txt'], c: 2, why: 'Paths starting with / are absolute.' },
    { q: '`cd -` does what?', a: ['Goes home', 'Goes to /', 'Returns to the previous directory', 'Deletes the folder'], c: 2, why: 'It toggles back to the last directory you were in.' }
  ],
  challenge: { task: 'In the Playground, navigate into the folder where Linux keeps its logs, then run pwd.', hint: 'Use an absolute path: cd /var/log', check: S => S.state.cwd === '/var/log' },
  next: `Looking isn't enough; you need to <b>build and destroy</b>. Next: create folders, copy, move, rename and delete files… including the one command that has no undo button.`,
  cheat: [['pwd', 'where am I'], ['ls -lah', 'list long/all/human'], ['cd /path', 'go (absolute)'], ['cd ..', 'up one level'], ['cd ~ / cd', 'go home'], ['cd -', 'previous directory'], ['tree', 'draw folder tree']]
});

/* ============ 05 FILES & DIRECTORIES ============ */
LESSONS.push({
  id: 'files-dirs', num: 5, cat: 'core', layer: 4, mins: 12,
  title: 'Files & Directories', short: 'Create, copy, move, delete',
  overview: `<p>Now you'll change the filesystem: <b>mkdir</b>, <b>touch</b>, <b>cp</b>, <b>mv</b>, <b>rm</b>, plus wildcards to act on many files at once. And you'll learn to respect <code>rm</code>, because Linux has <b>no Recycle Bin</b>.</p>`,
  hook: `<b>Make, Touch, Copy, Move, Remove</b> → "<b>M</b>y <b>T</b>ired <b>C</b>at <b>M</b>eows <b>R</b>arely".`,
  why: `Deploy scripts, Dockerfiles and CI pipelines are full of <code>mkdir -p</code>, <code>cp</code> and <code>mv</code>. Knowing their flags prevents broken builds and accidental data loss.`,
  scene: { type: 'tree', title: '~/project', items: [
    [0, 'project', '~/project', 'd'], [1, 'README.md', '', 'f'], [1, 'script.sh', '', 'f'],
    [1, 'src', 'mkdir -p src/utils', 'd', 0], [2, 'utils', '', 'd', 0],
    [2, 'main.py', 'mv app.py src/main.py', 'f', 3],
    [1, 'app.py', 'touch app.py', 'f', 1, 3],
    [1, 'app.py.bak', 'cp app.py app.py.bak', 'f', 2],
    [1, 'old-logs', 'about to be: rm -r old-logs', 'd', 0, 5]
  ] },
  steps: [
    { t: 'mkdir: make folders', sub: 'and -p for whole paths',
      body: `<p><code>mkdir src</code> creates one folder. <code>mkdir -p src/utils/helpers</code> creates the <b>whole chain</b>, including missing parents, and doesn't complain if they already exist.</p>`,
      analogy: `<code>mkdir -p</code> is like a <b>builder who constructs every missing floor</b> up to the one you asked for, instead of refusing because floor 2 doesn't exist yet.`,
      hook: `<b>-p = "Parents, please."</b> Builds every missing parent.`,
      words: ['mkdir', 'mkdir -p', 'parent directories'],
      focus: ['src', 'utils'],
      cmds: [{ c: 'mkdir -p src/utils', o: '', k: 'file', d: '~/project' }],
      cloud: `Scripts use <code>mkdir -p</code> because it's <b>idempotent</b>: running it twice is safe. Idempotency is a core DevOps idea (Ansible, Terraform).` },
    { t: 'touch: new empty file', sub: 'or update a timestamp',
      body: `<p><code>touch app.py</code> creates an empty file (or, if it exists, just updates its "last modified" time). Create many at once: <code>touch a.txt b.txt c.txt</code>.</p>`,
      analogy: `Touch is <b>placing a blank sheet of paper</b> on the desk, or tapping an existing sheet to say "I was just here".`,
      hook: `<b>Touch it and it exists.</b>`,
      words: ['touch', 'empty file', 'timestamp'],
      focus: ['app.py'],
      cmds: [{ c: 'touch app.py', o: '', k: 'file', d: '~/project' }, { c: 'ls', o: 'README.md  app.py  script.sh  src/', k: 'nav', d: '~/project' }] },
    { t: 'cp: copy', sub: 'cp SOURCE DEST, cp -r for folders',
      body: `<p><code>cp app.py app.py.bak</code> copies a file (great before editing a config!). To copy a whole folder you need <code>-r</code> (recursive): <code>cp -r src src-backup</code>.</p><p>Order is always <b>FROM → TO</b>.</p>`,
      analogy: `<code>cp</code> is a <b>photocopier</b>: the original stays, a duplicate appears.`,
      hook: `<b>"From → To."</b> Source first, destination second, always.`,
      words: ['cp src dest', 'cp -r', 'backup before editing'],
      focus: ['app.py', 'app.py.bak'],
      cmds: [{ c: 'cp app.py app.py.bak', o: '', k: 'file', d: '~/project' }, { c: 'sudo cp /etc/ssh/sshd_config /etc/ssh/sshd_config.bak', o: '', k: 'file' }],
      cloud: `Golden habit for production: <b>copy a config to .bak before editing it.</b> If the service won't start, you can restore in seconds.` },
    { t: 'mv: move & rename', sub: 'Linux has no rename command',
      body: `<p><code>mv</code> moves files. And because renaming is just "moving to a new name", <code>mv</code> renames too: <code>mv app.py main.py</code>.</p><p>Move + rename at once: <code>mv app.py src/main.py</code>. Unlike cp, folders don't need <code>-r</code>.</p>`,
      analogy: `<code>mv</code> is <b>picking up the paper and putting it elsewhere</b>, or relabeling the folder tab. No copy is left behind.`,
      hook: `<b>Rename = move to a new name.</b>`,
      words: ['mv', 'rename', 'mv -i (ask before overwrite)'],
      focus: ['main.py', 'src'],
      cmds: [{ c: 'mv app.py src/main.py', o: '', k: 'file', d: '~/project' }],
      warn: `<code>mv</code> and <code>cp</code> silently <b>overwrite</b> a destination that already exists. Add <code>-i</code> to be asked first.` },
    { t: 'rm: delete forever', sub: 'No recycle bin. No undo.',
      body: `<p><code>rm file</code> deletes a file. <code>rm -r folder</code> deletes a folder and everything in it. <code>-f</code> forces it without asking.</p><p>There is <b>no trash can</b>. Gone is gone. <code>rmdir</code> only removes <b>empty</b> folders, which makes it a safer choice.</p>`,
      analogy: `<code>rm</code> is a <b>paper shredder</b>, not a trash can. <code>rm -rf</code> is a <b>shredder with the safety guard removed</b>.`,
      hook: `<b>Read twice, rm once.</b> Especially anything with <code>-rf</code> or <code>*</code>.`,
      words: ['rm', 'rm -r', 'rm -f', 'rmdir', 'no undo'],
      focus: ['old-logs'],
      cmds: [{ c: 'rm -r old-logs', o: '', k: 'file', d: '~/project' }, { c: 'rm -rf /', o: "rm: it is dangerous to operate recursively on '/'\nrm: use --no-preserve-root to override this failsafe", k: 'file', x: 1 }],
      warn: `A stray space can be fatal: <code>rm -rf / tmp/junk</code> (space after /) targets the whole system. Modern rm refuses plain <code>/</code>, but it won't save you from <code>rm -rf ~/ *</code>. Always double-check the line and use <code>ls</code> with the same pattern first.` },
    { t: 'Wildcards', sub: '*  ?  [ ]  { }',
      body: `<p>Wildcards (globs) let one command hit many files:</p><p><code>*</code> = anything: <code>rm *.log</code><br><code>?</code> = exactly one character: <code>ls file?.txt</code><br><code>[abc]</code> = one of these: <code>ls report[12].pdf</code><br><code>{a,b}</code> = expand list: <code>mkdir {dev,staging,prod}</code></p>`,
      analogy: `<code>*</code> is a <b>joker card</b> that can stand for any cards. <code>?</code> is a joker for <b>exactly one</b> card.`,
      hook: `<b>Star = any amount. Question = exactly one.</b> Test with <code>ls</code> before <code>rm</code>!`,
      words: ['* wildcard', '? one char', '[abc]', '{a,b,c} brace expansion'],
      focus: ['project'],
      cmds: [{ c: 'mkdir -p env/{dev,staging,prod}', o: '', k: 'file', d: '~/project' }, { c: 'ls *.md', o: 'README.md', k: 'nav', d: '~/project' }] }
  ],
  summary: { title: 'You can shape the filesystem', sub: 'mkdir · touch · cp · mv · rm · globs', text: `<p>You can build structures (<code>mkdir -p</code>), copy safely (<code>cp</code>, back up first), move and rename (<code>mv</code>), delete with respect (<code>rm</code>), and target many files at once with wildcards.</p>` },
  quiz: [
    { q: 'How do you rename notes.txt to todo.txt?', a: ['rename notes.txt todo.txt', 'mv notes.txt todo.txt', 'cp -n notes.txt todo.txt', 'rn notes.txt todo.txt'], c: 1, why: 'Renaming is moving to a new name: mv old new.' },
    { q: 'Which creates a/b/c even if a and b don’t exist?', a: ['mkdir a/b/c', 'mkdir -r a/b/c', 'mkdir -p a/b/c', 'touch a/b/c'], c: 2, why: '-p creates missing parents.' },
    { q: 'You deleted a file with rm. How do you restore it?', a: ['From the Trash', 'undo', 'rm -u', 'You can’t, without a backup'], c: 3, why: 'rm has no recycle bin. Backups/snapshots are your only safety net.' },
    { q: 'Copy a whole folder:', a: ['cp folder new', 'cp -r folder new', 'mv -r folder new', 'cp -f folder new'], c: 1, why: '-r copies recursively (the folder and its contents).' }
  ],
  challenge: { task: 'In the Playground, create the file ~/project/src/app.py (the src folder doesn’t exist yet).', hint: 'mkdir -p ~/project/src && touch ~/project/src/app.py', check: S => !!S.get('/home/alice/project/src/app.py') },
  next: `You've got files. Now: <b>what's inside them?</b> Next lesson shows how to read a 2 GB log without crashing your terminal, watch logs <i>live</i>, and the famous puzzle every beginner hits: <b>how do you exit vim?</b>`,
  cheat: [['mkdir -p a/b', 'make folders + parents'], ['touch f', 'new empty file'], ['cp src dst', 'copy (-r for folders)'], ['mv src dst', 'move / rename'], ['rm f', 'delete (no undo!)'], ['rm -r dir', 'delete folder'], ['*  ?  {a,b}', 'wildcards']]
});

/* ============ 06 READING & EDITING ============ */
LESSONS.push({
  id: 'read-edit', num: 6, cat: 'core', layer: 4, mins: 12,
  title: 'Reading & Editing', short: 'cat, less, head, tail, nano, vim',
  overview: `<p>Linux configs and logs are <b>plain text</b>. You need to read short files, page through huge ones, peek at beginnings and ends, watch logs live, and edit configs on a server with no mouse.</p>`,
  hook: `<b>cat = whole, less = page, head = top, tail = bottom, tail -f = live.</b>`,
  why: `During an incident you'll <code>tail -f</code> an app log while editing a config in <code>nano</code> or <code>vim</code> over SSH. No GUI editor will be there to save you.`,
  scene: { type: 'graph', nodes: [
    { id: 'file', x: 450, y: 240, icon: 'log', label: 'app.log', sub: '2,000,000 lines', scale: 1.3 },
    { id: 'cat', x: 150, y: 110, icon: 'eye', label: 'cat', sub: 'dump everything' },
    { id: 'less', x: 150, y: 370, icon: 'book', label: 'less', sub: 'page by page', at: 1 },
    { id: 'head', x: 450, y: 75, icon: 'list', label: 'head', sub: 'first 10 lines', at: 2 },
    { id: 'tail', x: 750, y: 110, icon: 'list', label: 'tail -f', sub: 'live stream', at: 2 },
    { id: 'nano', x: 750, y: 370, icon: 'terminal', label: 'nano', sub: 'easy editor', at: 3 },
    { id: 'vim', x: 450, y: 410, icon: 'terminal', label: 'vim', sub: 'power editor', at: 4 }
  ], edges: [{ a: 'cat', b: 'file' }, { a: 'less', b: 'file', at: 1 }, { a: 'head', b: 'file', at: 2 }, { a: 'tail', b: 'file', at: 2 }, { a: 'nano', b: 'file', at: 3 }, { a: 'vim', b: 'file', at: 4 }] },
  steps: [
    { t: 'cat: print it all', sub: 'Great for short files',
      body: `<p><code>cat notes.txt</code> dumps the whole file to the screen. Perfect for short files. Add <code>-n</code> for line numbers.</p><p>On a 2-million-line log it will flood your terminal, so for big files use the next tools.</p>`,
      analogy: `<code>cat</code> is <b>dumping the whole box of papers on the floor</b>. Fine for 5 pages, terrible for 5,000.`,
      hook: `<b>cat = "conCATenate"</b> = glue files together and show them all.`,
      words: ['cat', 'cat -n', 'concatenate'],
      flow: { from: 'file', to: 'cat', label: 'cat notes.txt', detail: ['Linux is a kernel.', 'Everything is a file.'], color: 'teal' },
      cmds: [{ c: 'cat notes.txt', o: 'Linux is a kernel.\nEverything is a file.\nlinux is fun\nRemember: chmod 755 for scripts', k: 'text' }] },
    { t: 'less: page through', sub: 'Space, b, /search, q',
      body: `<p><code>less bigfile.log</code> opens a scrollable viewer that loads only what's on screen, so it's instant even on huge files.</p><p><b>Space</b> = next page, <b>b</b> = back, <b>/error</b> = search forward, <b>n</b> = next match, <b>G</b> = end, <b>g</b> = start, <b>q</b> = quit.</p>`,
      analogy: `<code>less</code> is a <b>book reader app</b>: one page at a time, with search.`,
      hook: `<b>"less is more"</b>: it shows less at once and gives you more control. <b>q</b> quits.`,
      words: ['less', '/search', 'n next', 'G end', 'q quit'],
      flow: { from: 'file', to: 'less', label: 'PAGE 1/80,000', detail: ['/ERROR → match 1 of 37'], color: 'purple' },
      cmds: [{ c: 'less /var/log/syslog', o: '(opens viewer · /ERROR to search · q to quit)', k: 'text' }] },
    { t: 'head & tail', sub: 'Top, bottom, and LIVE',
      body: `<p><code>head file</code> = first 10 lines; <code>tail file</code> = last 10. Choose a number with <code>-n</code>: <code>tail -n 50 app.log</code>.</p><p>The superstar: <code>tail -f app.log</code> <b>follows</b> the file, printing new lines as they're written. Press Ctrl+C to stop.</p>`,
      analogy: `<code>tail -f</code> is a <b>live CCTV feed</b>. <code>tail</code> without -f is a <b>still photo</b> of the last moments.`,
      hook: `<b>tail -f = follow.</b> Watch the log while you reproduce the bug.`,
      words: ['head -n', 'tail -n', 'tail -f', 'follow'],
      flow: { from: 'file', to: 'tail', label: 'LIVE', detail: ['09:05 GET /api 200', '09:05 GET /login 500 ✗'], color: 'red' }, focus: ['head', 'tail', 'file'],
      cmds: [{ c: 'head -n 2 notes.txt', o: 'Linux is a kernel.\nEverything is a file.', k: 'text' }, { c: 'sudo tail -f /var/log/auth.log', o: 'Nov 13 09:01:03 sshd[944]: Accepted publickey for alice\n(waiting for new lines… Ctrl+C to stop)', k: 'text' }],
      cloud: `Debugging a failing deploy: open one SSH window with <code>tail -f /var/log/nginx/error.log</code>, hit the site from another window, watch the error appear in real time.` },
    { t: 'nano: friendly editor', sub: 'Shortcuts printed on screen',
      body: `<p><code>nano file.conf</code> opens a simple editor. Just type. The shortcuts are listed at the bottom (<code>^</code> = Ctrl):</p><p><b>Ctrl+O</b> = save (Write Out), <b>Enter</b> to confirm · <b>Ctrl+X</b> = exit · <b>Ctrl+W</b> = search · <b>Ctrl+K</b> = cut line.</p><p>Editing system files needs root: <code>sudo nano /etc/hosts</code>.</p>`,
      analogy: `nano is <b>Notepad for the terminal</b>, with the cheat sheet glued to the bottom of the screen.`,
      hook: `<b>Ctrl+O = Output (save), Ctrl+X = eXit.</b>`,
      words: ['nano', 'Ctrl+O save', 'Ctrl+X exit', 'sudo nano'],
      flow: { from: 'nano', to: 'file', label: 'SAVE', detail: ['^O Write Out  ^X Exit'], color: 'green' },
      cmds: [{ c: 'sudo nano /etc/hosts', o: '(GNU nano 7.2   /etc/hosts — ^O save · ^X exit)', k: 'file' }] },
    { t: 'vim: survive it', sub: 'Modes: i to type, Esc, :wq',
      body: `<p><code>vim</code> is on almost every server and very powerful, but it's <b>modal</b>:</p><p><b>Normal mode</b> (starts here): keys are commands. Press <b>i</b> → <b>Insert mode</b>: now you type text. Press <b>Esc</b> → back to Normal.</p><p>Then type <b>:wq</b> Enter = write & quit · <b>:q!</b> = quit, throw away changes · <b>/word</b> = search · <b>dd</b> = delete line · <b>u</b> = undo.</p>`,
      analogy: `vim is a <b>car with a gearbox</b>: Normal mode is "park" (controls), Insert mode is "drive" (typing). Esc puts you back in park.`,
      hook: `<b>"i to Insert, Esc to Escape, :wq to Win & Quit, :q! to Quit in panic!"</b>`,
      words: ['vim', 'i insert', 'Esc', ':wq', ':q!', 'dd', 'u undo'],
      flow: { from: 'vim', to: 'file', label: ':wq', detail: ['write + quit'], color: 'amber' }, focus: ['vim', 'file'],
      cmds: [{ c: 'vim app.conf', o: '(-- INSERT -- after pressing i · Esc then :wq to save & quit)', k: 'file' }],
      warn: `Stuck in vim? Press <b>Esc</b> two or three times, then type <b>:q!</b> and Enter. You're free, and nothing was saved.` }
  ],
  summary: { title: 'You can read and edit anything', sub: 'Viewers + editors', text: `<p><code>cat</code> for short files, <code>less</code> for long, <code>head</code>/<code>tail</code> for edges, <code>tail -f</code> for live logs, <code>nano</code> for easy edits, and enough <code>vim</code> to never be trapped.</p>` },
  quiz: [
    { q: 'Watch a log as new lines arrive:', a: ['cat -f app.log', 'less -live app.log', 'tail -f app.log', 'head -f app.log'], c: 2, why: 'tail -f follows the file.' },
    { q: 'In vim, how do you save and quit?', a: ['Ctrl+S', 'Esc then :wq', 'Ctrl+X', 'q'], c: 1, why: 'Return to Normal mode with Esc, then :wq (write, quit).' },
    { q: 'Best tool to search inside a 3 GB log interactively?', a: ['cat', 'nano', 'less', 'touch'], c: 2, why: 'less loads lazily and supports /search.' },
    { q: 'In nano, Ctrl+O does what?', a: ['Open file', 'Save (write out)', 'Quit', 'Undo'], c: 1, why: 'Ctrl+O = Write Out (save). Ctrl+X exits.' }
  ],
  challenge: { task: 'Without an editor: create ~/hello.txt containing the text "hello linux" (hint: echo + >).', hint: 'echo "hello linux" > ~/hello.txt   then   cat ~/hello.txt', check: S => { const f = S.get('/home/alice/hello.txt'); return !!f && /hello linux/i.test(f.c); } },
  next: `You can read one file. But what if you don't know <b>which</b> file? Next: <code>find</code> and <code>grep</code>, the detective duo that searches millions of files in seconds. It's the skill that makes people think you're a hacker.`,
  cheat: [['cat f', 'print whole file'], ['less f', 'page through (q quits)'], ['head -n 20 f', 'first lines'], ['tail -n 50 f', 'last lines'], ['tail -f f', 'follow live'], ['nano f', 'easy editor (^O ^X)'], ['vim f', 'i · Esc · :wq · :q!']]
});
